"""Four independent faction profiles and catalogue links, without subfactions."""
import html,json,re
from pathlib import Path
from additional_realms_data import REALMS,DOCTRINES
from build_site_catalogue import build_records,render_card
ROOT=Path(__file__).resolve().parents[1];E=html.escape
LORE={
'v':('Life inside the crystal','Pure Veilglass awakens as a living people. The Veilborn seek a future beyond the commands imposed by the five older powers. Their secret campaign follows the five interwoven campaigns.','Advance behind powered growth nodes. Protect Resonators, take ground deliberately and withdraw damaged elites into the network.','Cut power, destroy the relay, then attack isolated crystal units. Their costly walkers cannot cover every front.'),
'u':('People erased from creation','Pure Veilglass preserves lives deleted from history. The Unwritten fight to become real again, rebuilding a community from names that the world has forgotten.','Use fast, fragile Memory Infantry and Decoy Echoes to draw fire. Preserve the Archive of Names and time Restoration around recent combat losses. Restored infantry are temporary.','Spread damage across fragile troops, deny the remnant area and attack the Archive. Decoys deal no damage; temporary echoes cannot create another memory.'),
'o':('Something beyond the realms','An alien presence enters through the gaps exposed by pure Veilglass. The Outer Silence seeks to extinguish thought rather than conquer territory.','Use cloaked Hush Stalkers and isolated flanking groups. Stillness Seers weaken targets; Null Leviathans finish close-range attacks. Absolute Silence creates a brief opening, not a permanent stun.','Bring detection, layer screens and maintain distance. Attacks or damage reveal Stalkers; the faction struggles to approach a prepared long-range line.'),
'n':('Heirs to a forbidden union','Hidden descendants of mortals and celestial beings emerge when the wars threaten their survival. They defend ancestral refuges alongside ordinary human attendants.','Build a small force of Oathbound Giants and Mountain Bearers, then keep vulnerable attendants close enough to support them. Commit carefully and use Earthbreaker against fortified ground positions.','Kite the giants, raid their slow economy and eliminate attendants. Their replacements are expensive; aircraft avoid Earthbreaker.')}

def main():
 records=build_records();sections=[];cards=[]
 for index,(p,r) in enumerate(REALMS.items(),6):
  family=r['family'];tag,lore,play,counter=LORE[p]
  roster=[a for a in records if a['faction']==family]
  scope='Secret sixth campaign. Authored roster; hidden from the normal lobby until campaign progression is implemented.' if p=='v' else 'Playable development skirmish faction. Appears only as a non-player faction in campaigns, usually neutral. No subfactions.'
  emblem='assets/roster/'+family+'-emblem.webp'
  sections.append(f'<section class="section independent-profile {family}" id="{family}"><header class="profile-heading"><img src="{emblem}" width="160" height="160" alt="{E(r["name"])} faction symbol"><div><p class="eyebrow">{E(tag)}</p><h2>{E(r["name"])}</h2><p>{E(lore)}</p><p class="scope">{E(scope)}</p></div></header><div class="profile-tactics"><div><h3>Specialisation</h3><p>{E(DOCTRINES[p])}</p></div><div><h3>Playing this faction</h3><p>{E(play)}</p></div><div><h3>Counterplay</h3><p>{E(counter)}</p></div></div><p><a href="forces.html?faction={family}">Filter the full field guide ↗</a> · <a href="campaigns.html">Campaign appearances and story ↗</a></p><div class="roster-grid">'+''.join(re.sub(r'<button class="art-button".*?data-art="([^"]+)">(.*?)</button>',r'<a class="art-button" href="\1" aria-label="View full artwork">\2</a>',render_card(a),flags=re.S).replace('id="'+a['id']+'"','id="profile-'+a['id']+'"') for a in roster)+'</div></section>')
  cards.append(f'<article class="faction {family}"><div class="faction-art"><img src="{emblem}" alt="{E(r["name"])} faction symbol" loading="lazy"></div><p class="faction-id">{index:02d} / {E(tag.upper())}</p><h3>{E(r["name"].upper())}</h3><p>{E(lore)}</p><div class="traits"><span>Independent faction</span><span>No subfactions</span></div><p>{E(DOCTRINES[p])}</p><p class="weakness">{E(scope)}</p><a class="faction-roster-link" href="additional-realms.html#{family}">Playstyle, buildings and units ↗</a></article>')
 nav=''.join(f'<a href="#{r["family"]}">{E(r["name"])}</a>' for r in REALMS.values())
 page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Veilborn and the Independent Factions | Sevenfall</title><meta name="description" content="Complete Veilborn, Unwritten, Outer Silence and Nephilim Remnant building and unit catalogues, faction stories, powers and counterplay. No subfactions."><link rel="stylesheet" href="site.css"><link rel="stylesheet" href="catalogue.css"><link rel="stylesheet" href="additional-realms.css"></head><body><a class="skip" href="#profiles">Skip to faction profiles</a><header class="topbar"><a class="logo" href="index.html">✦ SEVENFALL</a><nav aria-label="Main navigation"><a href="forces.html">Field Guide</a><a href="subfactions.html">Original Subfactions</a><a href="campaigns.html">Campaigns</a><a href="https://github.com/MrKrisSatan/Sevenfall">GitHub ↗</a></nav></header><main><section class="section guide-intro"><p class="eyebrow">FOUR INDEPENDENT FACTIONS / NO SUBFACTIONS</p><h1>Beyond the<br><em>five realms.</em></h1><p class="guide-lead">Living crystal, erased lives, alien silence and the heirs of an ancient union. Four complete faction rosters with distinct economies, armies, defenses, aircraft, beasts and building-bound superweapons.</p><p class="scope"><strong>Development expansion:</strong> these four factions are separate from the published five-faction alpha.3. The Unwritten, Outer Silence and Nephilim Remnant are unrestricted skirmish choices in the development game. Veilborn remains hidden pending legitimate campaign progression; the 150 mission briefs are designs, not 150 playable maps.</p><nav class="independent-picker" aria-label="Independent factions">'''+nav+'</nav></section><div id="profiles">'+''.join(sections)+'''</div><footer><p>Original painted sprite atlases, portraits and source prompts are provided in the repository. <a href="index.html#builds">Released build and scope</a>.</p></footer></main></body></html>'''
 (ROOT/'docs/additional-realms.html').write_text(page,encoding='utf-8')
 homepage=ROOT/'docs/index.html';s=homepage.read_text(encoding='utf-8')
 block='<!-- INDEPENDENT_REALMS_START -->\n<section class="section" id="independent-realms"><div class="section-heading"><span class="eyebrow">THE AWAKENING / DEVELOPMENT EXPANSION</span><h2>Four new peoples.<br><em>Four distinct armies.</em></h2><p>No subfactions. The Veilborn are the secret sixth campaign faction; the Unwritten, Outer Silence and Nephilim Remnant are skirmish factions and non-player campaign encounters.</p></div><div class="faction-grid">'+''.join(cards)+'</div></section>\n<!-- INDEPENDENT_REALMS_END -->'
 if '<!-- INDEPENDENT_REALMS_START -->' in s:s=re.sub(r'<!-- INDEPENDENT_REALMS_START -->.*?<!-- INDEPENDENT_REALMS_END -->',lambda _:block,s,flags=re.S)
 else:s=s.replace('<section class="section" id="arsenal">',block+'\n<section class="section" id="arsenal">')
 homepage.write_text(s,encoding='utf-8')
 print('Four independent faction profiles and 94 catalogue entries rendered.')
if __name__=='__main__':main()
